        let mut expected = charset_lowercase_hex();
        expected.extend(charset_digits());
        expected.sort_unstable();
        expected.dedup();
        assert_eq!(charset, expected);
        assert_eq!(charset.len(), 16); // 0-9 + a-f, no duplicates
    }

